-- Read only. Outside the lab, DuckDB attaches a lake with:
--   ATTACH 'ducklake:metadata.ducklake' AS lake (DATA_PATH 'data/');
-- The Lakehouse Lab attaches each mission's lake itself (ATTACH is refused there).
CREATE TABLE lake.orders AS SELECT 1 AS id, 40 AS amount;
INSERT INTO lake.orders VALUES (2, 15);
UPDATE lake.orders SET amount = 45 WHERE id = 1;
SELECT * FROM lake.snapshots();
SELECT * FROM lake.orders AT (VERSION => 2);
SELECT * FROM lake.table_changes('orders', 2, 3);
